    pub(crate) fn compare_general_parameter(
        &self,
        other: &Document,
        a: &GeneralParameter,
        b: &GeneralParameter,
        path: &str,
    ) -> Result<(), String> {
        self.compare_identifiable(other, a.base(), b.base(), path)?;
        let list_a = a.get_prm_char();
        let list_b = b.get_prm_char();
        if list_a.len() != list_b.len() {
            return Err(format!("{path}: PRM_CHAR length mismatch"));
        }
        for (index, (x, y)) in list_a.iter().zip(list_b.iter()).enumerate() {
            let x = self
                .prm_chars
                .get(*x)
                .ok_or_else(|| format!("{path}.PRM_CHAR[{index}]: id not found in own arena"))?;
            let y = other
                .prm_chars
                .get(*y)
                .ok_or_else(|| format!("{path}.PRM_CHAR[{index}]: id not found in other arena"))?;
            self.compare_prm_char(other, x, y, &format!("{path}.PRM_CHAR[{index}]"))?;
        }
        Ok(())
    }

